import ast, io, contextlib
def _binds_shipping(s):
    if isinstance(s, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return s.name == 'shipping'
    targets = s.targets if isinstance(s, ast.Assign) else [s.target] if isinstance(s, (ast.AnnAssign, ast.AugAssign)) else []
    return any(isinstance(n, ast.Name) and n.id == 'shipping' for t in targets for n in ast.walk(t))
_tree = ast.parse(__source__)
_body = []
for _s in _tree.body:
    _body.append(_s)
    if _binds_shipping(_s):
        _body.append(ast.Assign([ast.Name('shipping', ast.Store())], ast.Name('__shipping__', ast.Load())))
_tree.body = _body
ast.fix_missing_locations(_tree)
_g = {'__builtins__': __builtins__, '__shipping__': lambda w: 100.0}
with contextlib.redirect_stdout(io.StringIO()):
    exec(compile(_tree, '<rerun>', 'exec'), _g)
assert _g['order_total'](1, 1, 1) == 101.0, 'order_total should call shipping instead of repeating its formula'

